import math

def get_units(m):
    """Returns the set of units in Z_m^*."""
    units = []
    for x in range(1, m):
        if math.gcd(x, m) == 1:
            units.append(x)
    return units

def calculate_Nm_prime(m_prime):
    """Calculates the number of cycles N_{m'} for the map x -> 3x mod m' on Z_{m'}^*."""
    if m_prime == 1:
        return 0 # Should not happen based on N_c(m) formulation

    units = get_units(m_prime)
    if not units:
        # This happens if m_prime = 1 or m_prime = 2 (Z_2^* = {1})
        # If m_prime=1, units is empty. If m_prime=2, units=[1].
        if m_prime == 2:
            return 1
        return 0

    visited = set()
    cycle_count = 0

    for start_element in units:
        if start_element not in visited:
            cycle_count += 1
            current = start_element
            while current not in visited:
                visited.add(current)
                current = (3 * current) % m_prime

    return cycle_count

def find_Nc_m(m):
    """Calculates the total number of cycles N_c(m) for the permutation x -> 3x mod m on {1, ..., m-1}."""
    if math.gcd(3, m) != 1:
        # Should not happen based on problem constraints
        return None

    divisors = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divisors.append(i)
            if i*i != m:
                divisors.append(m // i)

    # We sum N_{m'} for m' that are divisors of m and m' > 1.
    total_cycles = 0
    for m_prime in divisors:
        if m_prime > 1:
            total_cycles += calculate_Nm_prime(m_prime)

    return total_cycles

